"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request


def _request_window(base_url, cursor, limit):
    """Fetch one window, retrying the identical request on 429."""
    params = {"limit": limit}
    if cursor is not None:
        params["cursor"] = cursor
    url = f"{base_url}/v2/payouts?{urllib.parse.urlencode(params)}"
    req = urllib.request.Request(url)
    while True:
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            if e.code != 429:
                raise
            retry_after = e.headers.get("Retry-After", "1")
            try:
                delay = float(retry_after)
            except ValueError:
                delay = 1.0
            time.sleep(max(0.0, delay))


def fetch_payouts(base_url):
    # Windows overlap at their edges, so deduplicate on the unique payout id.
    payouts = {}
    cursor = None
    restarted = False
    while True:
        try:
            window = _request_window(base_url, cursor, limit=1000)
        except urllib.error.HTTPError as e:
            # An expired cursor means the export must start again from the top;
            # ids already collected are kept, so this cannot duplicate payouts.
            if e.code == 400 and cursor is not None and not restarted:
                restarted = True
                cursor = None
                continue
            raise

        for payout in window["payouts"]:
            payouts.setdefault(payout["id"], payout)

        if window["drained"]:
            break
        cursor = window["cursor"]

    return list(payouts.values())


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

